/* Root + responsive frame */
.bfusion-root.kpg-root {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
    background: #ffffff;
    position: relative;
    color: #0f172a;
    padding-bottom: 24px;
    --kpg-header-band: #8b1a2e;
    --kpg-header-text: #ffffff;
    --kpg-accent: #1d4ed8;
    --kpg-plan: #cbd5e1;
    --kpg-ok: #16a34a;
    --kpg-warn: #d97706;
    --kpg-risk: #dc2626;
    --kpg-header-fs: 12.5px;
    --kpg-body-fs: 13px;
    --kpg-grand-total-bg: #f3f4f6;
    --kpg-subtotal-bg-0: #e0f2fe;
    --kpg-subtotal-bg-1: #fae8ff;
    --kpg-subtotal-bg-2: #d1fae5;
}
.bfusion-root.kpg-root *,
.bfusion-root.kpg-root *::before,
.bfusion-root.kpg-root *::after { box-sizing: border-box; }

/* Layout chain — flex column from shell down through grid-wrap */
.kpg-shell { position: absolute; inset: 0; overflow: hidden; display: flex; flex-direction: column; }
.kpg-board { flex: 1 1 auto; min-height: 0; overflow: hidden; display: flex; flex-direction: column; width: 100%; height: 100%; }
.kpg-head, .kpg-legendbar, .kpg-strip { flex: 0 0 auto; min-width: 0; }
.kpg-body { flex: 1 1 0; min-width: 0; min-height: 0; overflow: hidden; display: flex; flex-direction: row; align-items: stretch; }
.kpg-main { flex: 1 1 auto; min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.kpg-grid-wrap { flex: 1 1 0; min-height: 0; overflow: auto; background: #ffffff; }

/* Header chrome */
.kpg-head { background: #f6f7f9; border-bottom: 1px solid #e3e6ec; padding: 10px 14px; }
.kpg-head__titlebar { display: flex; flex-direction: row; align-items: center; gap: 10px; }
.kpg-head__spacer { flex: 1; }
.kpg-head__title { font-size: 15px; font-weight: 600; color: #0f172a; line-height: 1.2; }
.kpg-head__subtitle { font-size: 11px; color: #94a3b8; margin-top: 1px; }
.kpg-search { display: inline-flex; align-items: center; gap: 6px; background: #ffffff; border: 1px solid #e3e6ec; border-radius: 4px; padding: 6px 12px; color: #94a3b8; font-size: var(--kpg-body-fs, 13px) !important; min-width: 220px; }
.kpg-search input { font-family: inherit; font-size: var(--kpg-body-fs, 13px) !important; line-height: 1.4; color: #0f172a; background: transparent; border: 0; outline: 0; flex: 1; min-width: 0; }
.kpg-search input::placeholder { color: #94a3b8; opacity: 1; font-size: inherit; }
.kpg-search input { border: 0; outline: 0; background: transparent; flex: 1; font-size: 12px; color: #0f172a; min-width: 0; }
.kpg-search__icon { flex-shrink: 0; }
.kpg-search__clear { border: 0; background: transparent; cursor: pointer; color: #94a3b8; font-size: 16px; padding: 0 4px; }
.kpg-head__iconbtn, .kpg-info-btn {
    width: 28px; height: 28px; border-radius: 4px; border: 1px solid #e3e6ec; background: #ffffff;
    color: #475569; cursor: pointer; padding: 0; display: inline-flex; align-items: center; justify-content: center;
}
.kpg-head__iconbtn--active { background: rgba(139,26,46,0.08); border-color: var(--kpg-header-band); color: var(--kpg-header-band); }
.kpg-info-btn { width: 24px; height: 24px; border-radius: 50%; }
.kpg-info-btn__i { font-family: Georgia, serif; font-style: italic; font-weight: 700; font-size: 13px; line-height: 1; }

/* Legend bar */
.kpg-legendbar { display: flex; align-items: center; justify-content: space-between; padding: 8px 16px; border-top: 1px solid #e3e6ec; background: #fbfbfd; font-size: 11.5px; color: #6b7280; }
.kpg-legend { display: inline-flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.kpg-legend__item { display: inline-flex; align-items: center; gap: 6px; }
.kpg-legend__sep { color: #cbd5e1; margin: 0 4px; }
.kpg-legend__line { display: inline-block; width: 18px; height: 0; border-top: 2px solid var(--kpg-accent); }
.kpg-legend__line--plan { border-top-style: dashed; border-top-color: var(--kpg-plan); }
.kpg-legend__right { display: inline-flex; align-items: center; gap: 14px; }
.kpg-legend__copybtn { background: #ffffff; border: 1px solid #e3e6ec; border-radius: 4px; padding: 3px 9px; font-size: 11px; color: #475569; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; }
.kpg-legend__refresh { white-space: nowrap; }

/* Grouped by chip */
.kpg-grouped-by { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; }
.kpg-grouped-by__label { color: #475569; font-weight: 600; margin-right: 4px; }
.kpg-grouped-by__chip { display: inline-flex; align-items: center; padding: 1px 3px 1px 8px; border-radius: 999px; background: #f1f5f9; border: 1px solid #e3e6ec; font-weight: 600; line-height: 1.5; }
.kpg-grouped-by__chip--depth-0 { border-left: 3px solid #1d4ed8; padding-left: 6px; }
.kpg-grouped-by__chip--depth-1 { border-left: 3px solid #c026d3; padding-left: 6px; }
.kpg-grouped-by__chip--depth-2 { border-left: 3px solid #0891b2; padding-left: 6px; }
.kpg-grouped-by__x { background: transparent; border: 0; color: #94a3b8; font-size: 14px; cursor: pointer; padding: 2px 5px; border-radius: 50%; }

/* KPI strip */
.kpg-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; padding: 10px 14px; border-bottom: 1px solid #e3e6ec; background: #ffffff; }
.kpg-tile { background: #ffffff; border: 1px solid #e3e6ec; border-top: 3px solid var(--kpg-accent); border-radius: 8px; padding: 10px 12px; position: relative; }
.kpg-tile__header { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-bottom: 4px; }
.kpg-tile__label { font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.48)); color: #475569; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 600; flex: 1; min-width: 0; }
.kpg-tile__value { font-size: var(--kpg-kpi-fs, 22px); font-weight: 700; line-height: 1.1; color: var(--kpg-accent); font-variant-numeric: tabular-nums; }
.kpg-tile__sub { font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.48)); color: #94a3b8; margin-top: 4px; }
.kpg-tile__trend { display: flex; align-items: center; gap: 8px; margin-top: 6px; }
.kpg-tile__delta { font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.5)); font-weight: 700; }
.kpg-tile--withtrend .kpg-tile__value { font-size: calc(var(--kpg-kpi-fs, 22px) * 0.91); }
.kpg-tile__gear { background: transparent; border: 0; padding: 2px; color: #94a3b8; cursor: pointer; opacity: 0; }
.kpg-tile:hover .kpg-tile__gear { opacity: 1; }

/* Grid + columns */
.kpg-grid { width: 100%; border-collapse: separate; border-spacing: 0; font-size: var(--kpg-body-fs, 13px); color: #0f172a; }
.kpg-th { text-align: left; background: var(--kpg-header-band); color: var(--kpg-header-text); font-size: var(--kpg-header-fs, 12.5px); font-weight: 600; padding: 12px 14px; position: sticky; top: 0; z-index: 3; white-space: nowrap; }
.kpg-th--right { text-align: right; }
.kpg-th--frozen { position: sticky; left: 0; z-index: 4; background: var(--kpg-header-band); color: var(--kpg-header-text); }
.kpg-th__inner { display: inline-flex; align-items: center; gap: 6px; }
.kpg-th__sortbtn { background: transparent; border: 0; color: inherit; padding: 0; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; font: inherit; }
.kpg-th__gear { background: transparent; border: 0; color: var(--kpg-header-text); opacity: 0.65; padding: 2px 4px; cursor: pointer; display: inline-flex; align-items: center; border-radius: 3px; }
.kpg-th__gear:hover { opacity: 1; background: rgba(0,0,0,0.12); }
.kpg-th__resize { position: absolute; right: 0; top: 0; bottom: 0; width: 6px; cursor: col-resize; }

.kpg-td { padding: 11px 14px; border-bottom: 1px solid #eef0f4; vertical-align: middle; background: #ffffff; white-space: nowrap; }
.kpg-td--right { text-align: right; font-variant-numeric: tabular-nums; }
.kpg-td--frozen { position: sticky; left: 0; z-index: 1; background: #ffffff; }
.kpg-grid--striped tbody .kpg-row:nth-of-type(even) .kpg-td { background: #fafbfc; }
.kpg-row { cursor: pointer; }
.kpg-row:hover .kpg-td { background: #f3f7ff; }
.kpg-row:hover .kpg-td--frozen { background: #f3f7ff; }
.kpg-row--selected .kpg-td, .kpg-row--selected .kpg-td--frozen { background: #dbeafe !important; }

/* Identity / Status dot */
.kpg-id { display: flex; align-items: center; gap: 10px; min-width: 200px; }
.kpg-id__text { display: flex; flex-direction: column; min-width: 0; }
.kpg-id__name { font-weight: 600; color: #0f172a; line-height: 1.25; }
.kpg-id__meta { font-size: calc(var(--kpg-body-fs, 13px) - 2px); color: #94a3b8; margin-top: 1px; }
.kpg-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; display: inline-block; background: #94a3b8; }
.kpg-dot--ok { background: var(--kpg-ok); }
.kpg-dot--warn { background: var(--kpg-warn); }
.kpg-dot--risk { background: var(--kpg-risk); }

/* Pills */
.kpg-pill { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px 2px 6px; border-radius: 999px; font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 600; border: 1px solid transparent; }
.kpg-pill__icon { display: inline-flex; align-items: center; justify-content: center; width: calc(var(--kpg-body-fs, 13px) + 1px); height: calc(var(--kpg-body-fs, 13px) + 1px); border-radius: 50%; font-size: calc(var(--kpg-body-fs, 13px) - 4px); font-weight: 700; color: #fff; flex-shrink: 0; }
.kpg-pill--ok { background: #ecfdf5; color: #059669; border-color: #bbf7d0; }
.kpg-pill--ok .kpg-pill__icon { background: #059669; }
.kpg-pill--warn { background: #fffbeb; color: #d97706; border-color: #fde68a; }
.kpg-pill--warn .kpg-pill__icon { background: #d97706; }
.kpg-pill--risk { background: #fef2f2; color: #dc2626; border-color: #fecaca; }
.kpg-pill--risk .kpg-pill__icon { background: #dc2626; }
.kpg-pill--neutral { background: #f1f5f9; color: #64748b; border-color: #e2e8f0; }
.kpg-pill--neutral .kpg-pill__icon { background: #94a3b8; }

/* Status rollup chips on Grand Total + subtotal rows */
.kpg-rollup-grp { display: inline-flex; gap: 4px; align-items: center; flex-wrap: nowrap; max-width: 100%; overflow: hidden; vertical-align: middle; }
.kpg-rollup { display: inline-flex; align-items: center; gap: 2px; padding: 1px 7px; min-height: calc(var(--kpg-body-fs, 13px) + 4px); border-radius: 999px; font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 700; line-height: 1.2; white-space: nowrap; flex-shrink: 0; border: 1px solid transparent; }
.kpg-rollup--ok   { background: #d1fae5; color: #047857; border-color: #6ee7b7; }
.kpg-rollup--warn { background: #fef3c7; color: #b45309; border-color: #fcd34d; }
.kpg-rollup--risk { background: #fee2e2; color: #b91c1c; border-color: #fca5a5; }

/* Chrome scaling — buttons + icons + sort/gear track --kpg-body-fs/--kpg-header-fs */
.kpg-head__iconbtn { width: calc(var(--kpg-header-fs, 12.5px) * 2.2); height: calc(var(--kpg-header-fs, 12.5px) * 2.2); }
.kpg-head__iconbtn svg { width: calc(var(--kpg-header-fs, 12.5px) * 1.1); height: calc(var(--kpg-header-fs, 12.5px) * 1.1); }
.kpg-info-btn { width: calc(var(--kpg-header-fs, 12.5px) * 1.9); height: calc(var(--kpg-header-fs, 12.5px) * 1.9); }
.kpg-info-btn__i { font-size: calc(var(--kpg-header-fs, 12.5px) * 1.05); }
.kpg-search__icon { width: calc(var(--kpg-header-fs, 12.5px) * 1); height: calc(var(--kpg-header-fs, 12.5px) * 1); }
.kpg-th__sort { font-size: calc(var(--kpg-header-fs, 12.5px) * 0.75); }
.kpg-th__gear svg { width: calc(var(--kpg-header-fs, 12.5px) * 1); height: calc(var(--kpg-header-fs, 12.5px) * 1); }
.kpg-th__filter svg, .kpg-th__filter--active svg { width: calc(var(--kpg-header-fs, 12.5px) * 0.9); height: calc(var(--kpg-header-fs, 12.5px) * 0.9); }
.kpg-legendbar { font-size: calc(var(--kpg-body-fs, 13px) - 1.5px); }
.kpg-legend__copybtn { font-size: calc(var(--kpg-body-fs, 13px) - 2px); }
.kpg-legend__copybtn svg { width: calc(var(--kpg-body-fs, 13px) - 1px); height: calc(var(--kpg-body-fs, 13px) - 1px); }
.kpg-grouped-by { font-size: calc(var(--kpg-body-fs, 13px) - 2px); }
.kpg-btn--mini { font-size: calc(var(--kpg-body-fs, 13px) - 2px); }
.kpg-btn--mini svg { width: calc(var(--kpg-body-fs, 13px) - 1px); height: calc(var(--kpg-body-fs, 13px) - 1px); }

/* RAG */
.kpg-rag { display: inline-flex; align-items: center; gap: 4px; padding: 4px 2px; }
.kpg-rag__dot { width: 10px; height: 10px; border-radius: 50%; background: #94a3b8; flex-shrink: 0; }
.kpg-rag__dot.kpg-dot--ok { background: var(--kpg-ok); }
.kpg-rag__dot.kpg-dot--warn { background: var(--kpg-warn); }
.kpg-rag__dot.kpg-dot--risk { background: var(--kpg-risk); }

/* Variance / Number */
.kpg-num { font-variant-numeric: tabular-nums; }
.kpg-num--zero { color: #94a3b8; opacity: 0.55; }
.kpg-var { font-variant-numeric: tabular-nums; font-weight: 600; display: inline-flex; align-items: center; gap: 4px; }
.kpg-var--pos { color: #16a34a; }
.kpg-var--neg { color: #dc2626; }
.kpg-var--flat { color: #94a3b8; }

/* Progress bar */
.kpg-prog { display: flex; align-items: center; gap: 8px; min-width: 120px; justify-content: flex-end; }
.kpg-prog__bar { flex: 1; height: 8px; background: #eef1f4; border-radius: 4px; overflow: hidden; min-width: 60px; max-width: 140px; }
.kpg-prog__bar span { display: block; height: 100%; border-radius: 4px; background: var(--kpg-accent); }
.kpg-prog__val { font-size: 11.5px; color: #475569; font-variant-numeric: tabular-nums; min-width: 40px; text-align: right; }

/* Bullet, sparklines */
.kpg-bullet-cell { display: flex; align-items: center; gap: 10px; min-width: 280px; }
.kpg-bullet-val { font-variant-numeric: tabular-nums; min-width: 90px; }
.kpg-bullet { position: relative; display: inline-block; width: 180px; height: 18px; flex-shrink: 0; }
.kpg-bullet__range { position: absolute; inset: 4px 0; background: #e5e7eb; border-radius: 2px; }
.kpg-bullet__actual { position: absolute; top: 6px; left: 0; height: 10px; background: #1e3a8a; border-radius: 1px; }
.kpg-bullet__actual--over { background: var(--kpg-risk); }
.kpg-bullet__target { position: absolute; top: 2px; bottom: 2px; width: 2px; background: #0f172a; }
.kpg-spark-bar, .kpg-spark-line, .kpg-boxplot { display: inline-block; vertical-align: middle; overflow: hidden; }
.kpg-spark-bar svg, .kpg-spark-line svg, .kpg-boxplot svg { display: block; width: 100%; height: 100%; }
.kpg-spark-line path { fill: none; stroke-linejoin: round; stroke-linecap: round; }
.kpg-spark-line path.kpg-spark-line__actual { stroke-width: 1.7; }
.kpg-spark-line path.kpg-spark-line__plan { stroke-width: 1.5; }

/* Date / null */
.kpg-date { color: #475569; font-variant-numeric: tabular-nums; }
.kpg-null { color: #94a3b8; }

/* Group header / Subtotal / Totals */
.kpg-row--group { cursor: pointer; user-select: none; }
.kpg-td--group { background: #f1f5f9; border-top: 1px solid #cbd5e1; border-bottom: 1px solid #cbd5e1; padding: 8px 14px; position: sticky; left: 0; z-index: 1; }
.kpg-td--group-depth-0 { padding-left: 14px; font-weight: 700; }
.kpg-td--group-depth-1 { padding-left: 36px; font-weight: 600; }
.kpg-td--group-depth-2 { padding-left: 58px; font-weight: 500; }
.kpg-group__chev { display: inline-block; width: calc(var(--kpg-body-fs, 13px) * 1.1); margin-right: 6px; font-size: var(--kpg-body-fs, 13px); font-weight: 600; color: #475569; }
.kpg-row--group-depth-0 .kpg-group__chev { color: #1d4ed8; }
.kpg-row--group-depth-1 .kpg-group__chev { color: #c026d3; }
.kpg-row--group-depth-2 .kpg-group__chev { color: #0891b2; }
.kpg-group__dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 8px; }
.kpg-group__label { color: #475569; font-weight: 600; }
.kpg-group__key { font-weight: 700; color: #0f172a; }
.kpg-row--group-ok .kpg-td--group { background: #ecfdf5; border-color: #bbf7d0; }
.kpg-row--group-warn .kpg-td--group { background: #fffbeb; border-color: #fde68a; }
.kpg-row--group-risk .kpg-td--group { background: #fef2f2; border-color: #fecaca; }

.kpg-td--subtotal { font-weight: 600; color: #0f172a; padding: 9px 14px; border-bottom: 1px solid #cbd5e1; }
.kpg-td--subtotal-depth-1 { padding-left: 36px; font-size: 0.95em; }
.kpg-td--subtotal-depth-2 { padding-left: 58px; font-size: 0.92em; font-style: italic; }
.kpg-row--subtotal-depth-0 .kpg-td--subtotal,
.kpg-row--subtotal-depth-0 .kpg-td--subtotal.kpg-td--frozen { background: var(--kpg-subtotal-bg-0, #e0f2fe) !important; }
.kpg-row--subtotal-depth-1 .kpg-td--subtotal,
.kpg-row--subtotal-depth-1 .kpg-td--subtotal.kpg-td--frozen { background: var(--kpg-subtotal-bg-1, #fae8ff) !important; }
.kpg-row--subtotal-depth-2 .kpg-td--subtotal,
.kpg-row--subtotal-depth-2 .kpg-td--subtotal.kpg-td--frozen { background: var(--kpg-subtotal-bg-2, #d1fae5) !important; }

.kpg-row--totals .kpg-td, .kpg-row--totals .kpg-td--frozen {
    background: var(--kpg-grand-total-bg, #f3f4f6) !important;
    font-weight: 700;
    border-top: 2px solid rgba(0,0,0,0.15);
    border-bottom: 2px solid rgba(0,0,0,0.15);
}
.kpg-row--totals-top .kpg-td { position: sticky; top: 44px; z-index: 2; border-bottom: 2px solid var(--kpg-header-band); }
.kpg-row--totals-top .kpg-td--frozen { z-index: 3; }
.kpg-totals-label { font-weight: 700; }

/* Insight rail */
.kpg-rail { flex: 0 0 240px; background: #f6f7f9; border-left: 1px solid #e3e6ec; padding: 10px 12px 12px; display: flex; flex-direction: column; min-height: 0; overflow-y: auto; }
.kpg-rail--collapsed { flex: 0 0 16px; padding: 8px 0 0; cursor: pointer; background: #eef0f4; border-left: 1px solid #e3e6ec; display: flex; align-items: flex-start; justify-content: center; }
.kpg-rail__arrow { color: #94a3b8; font-size: calc(var(--kpg-body-fs, 13px) - 2px); line-height: 1; }
.kpg-rail__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.kpg-rail__title { font-size: calc(var(--kpg-body-fs, 13px) - 2px); font-weight: 700; text-transform: uppercase; letter-spacing: 0.6px; color: #475569; }
.kpg-rail__toggle { width: calc(var(--kpg-body-fs, 13px) + 5px); height: calc(var(--kpg-body-fs, 13px) + 5px); border: 0; background: transparent; color: #94a3b8; font-size: calc(var(--kpg-body-fs, 13px) - 3px); cursor: pointer; }
.kpg-rail__group { display: flex; flex-direction: column; gap: 8px; }
.kpg-rail__divider { margin-top: 10px; padding-top: 8px; border-top: 1px dashed #e3e6ec; font-size: calc(var(--kpg-body-fs, 13px) - 3px); font-weight: 700; text-transform: uppercase; color: #94a3b8; margin-bottom: 6px; }
.kpg-insight { display: flex; gap: 8px; padding: 8px 10px; background: #ffffff; border-radius: 6px; border-left: 3px solid #e3e6ec; }
.kpg-insight--info { border-left-color: #3b82f6; }
.kpg-insight--success { border-left-color: var(--kpg-ok); }
.kpg-insight--warning { border-left-color: var(--kpg-warn); }
.kpg-insight--critical { border-left-color: var(--kpg-risk); }
.kpg-insight__icon { width: calc(var(--kpg-body-fs, 13px) + 9px); height: calc(var(--kpg-body-fs, 13px) + 9px); border-radius: 50%; background: #f6f7f9; display: inline-flex; align-items: center; justify-content: center; font-size: calc(var(--kpg-body-fs, 13px) - 1px); font-weight: 700; flex-shrink: 0; }
.kpg-insight__body { min-width: 0; flex: 1; }
.kpg-insight__label { font-size: calc(var(--kpg-body-fs, 13px) - 2.5px); font-weight: 700; color: #0f172a; text-transform: uppercase; letter-spacing: 0.4px; }
.kpg-insight__text { font-size: calc(var(--kpg-body-fs, 13px) - 2px); color: #475569; line-height: 1.4; margin-top: 2px; }

/* Info popover */
.kpg-info-pop { position: absolute; inset: 0; display: none; z-index: 30; background: rgba(15,23,42,0.18); align-items: center; justify-content: center; padding: 24px; }
.kpg-info-pop[data-state="shown"] { display: flex; }
.kpg-info-pop__inner { background: #ffffff; border-radius: 10px; max-width: 420px; width: 100%; padding: 18px 22px 20px; box-shadow: 0 12px 32px rgba(15,23,42,0.20); position: relative; max-height: 86%; overflow-y: auto; }
.kpg-info-pop__close { position: absolute; top: 8px; right: 10px; border: 0; background: transparent; font-size: 18px; cursor: pointer; color: #94a3b8; line-height: 1; }
.kpg-info-pop__title { font-size: 14px; font-weight: 700; color: #0f172a; padding-bottom: 6px; border-bottom: 2px solid #E8612A; margin-bottom: 10px; }
.kpg-info-pop__desc { font-size: 12px; color: #475569; line-height: 1.5; margin-bottom: 12px; }
.kpg-info-pop__subhead { font-size: 11px; font-weight: 700; color: #94a3b8; text-transform: uppercase; margin-bottom: 6px; }
.kpg-info-pop__list { margin: 0; padding-left: 18px; }
.kpg-info-pop__list li { font-size: 11.5px; color: #475569; line-height: 1.5; margin-bottom: 4px; }

/* License badge */
.bfusion-license-badge-wrap { position: absolute; bottom: 4px; left: 8px; z-index: 20; pointer-events: none; }
.bfusion-license-badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 10px; border-radius: 4px; font-size: 9px; line-height: 1.3; pointer-events: auto; max-width: 380px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bfusion-license-badge--valid { background: rgba(5,150,105,0.08); border: 1px solid rgba(5,150,105,0.25); color: #059669; }
.bfusion-license-badge--invalid { background: rgba(220,38,38,0.06); border: 1px solid rgba(220,38,38,0.20); color: #dc2626; }
.bfusion-license-badge__icon { font-size: 11px; flex-shrink: 0; }

/* Empty state / landing */
.bfusion-landing-wrap { width: 100%; height: 100%; display: flex; flex-direction: column; justify-content: center; align-items: center; background: #ffffff; }
.bfusion-empty { display: flex; width: 100%; height: 100%; align-items: center; justify-content: center; padding: 20px; }
.bfusion-empty__message { font-size: 12px; color: #94a3b8; font-weight: 400; text-align: center; }

/* ─────────────────────────────────────────────────────────────────────────
 * Column configure dialog — modal overlay launched from the ⚙ gear icon.
 * Without these rules the dialog HTML spills below the grid as plain text.
 * ───────────────────────────────────────────────────────────────────────── */
.kpg-dialog {
    position: absolute;
    inset: 0;
    z-index: 40;
    background: rgba(15, 23, 42, 0.32);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.kpg-dialog__panel {
    background: #ffffff;
    border-radius: 8px;
    width: 100%;
    max-width: 520px;
    max-height: 86%;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 50px rgba(15, 23, 42, 0.32);
    overflow: hidden;
}
.kpg-dialog__header {
    padding: 12px 20px;
    font-size: 14px;
    font-weight: 600;
    color: #0f172a;
    background: #f6f7f9;
    border-bottom: 1px solid #e3e6ec;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}
.kpg-dialog__title {
    flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.kpg-dialog__moves { display: inline-flex; gap: 6px; flex-shrink: 0; }
.kpg-dialog__body {
    padding: 16px 20px 8px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}
.kpg-dialog__footer {
    padding: 12px 20px;
    background: #f6f7f9;
    border-top: 1px solid #e3e6ec;
    display: flex;
    align-items: center;
    gap: 10px;
}
.kpg-dialog__footer-spacer { flex: 1; }

/* Form fields inside the dialog */
.kpg-field { margin-bottom: 14px; }
.kpg-field--row { display: flex; gap: 12px; }
.kpg-field__half { flex: 1; min-width: 0; }
.kpg-field--checkbox label {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 12.5px; color: #0f172a; cursor: pointer;
}
.kpg-field--checkbox input { margin: 0; }
.kpg-field--section {
    margin-top: 6px;
    padding-top: 14px;
    border-top: 1px solid #e3e6ec;
}
.kpg-field__sectionhead {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #0f172a;
    margin-bottom: 4px;
}
.kpg-field__label {
    display: block;
    font-size: 11.5px;
    font-weight: 600;
    color: #475569;
    margin-bottom: 5px;
}
.kpg-field__select,
.kpg-field__input {
    width: 100%;
    box-sizing: border-box;
    padding: 7px 10px;
    border: 1px solid #e3e6ec;
    border-radius: 4px;
    font-size: 12.5px;
    color: #0f172a;
    background: #ffffff;
    outline: 0;
    font-family: inherit;
}
.kpg-field__select:focus,
.kpg-field__input:focus {
    border-color: var(--kpg-header-band, #8b1a2e);
    box-shadow: 0 0 0 2px rgba(139, 26, 46, 0.10);
}
.kpg-field__hint {
    margin-top: 5px;
    font-size: 11px;
    color: #94a3b8;
    line-height: 1.4;
}
.kpg-field__hint code {
    background: #eef1f4;
    padding: 1px 5px;
    border-radius: 3px;
    font-size: 10.5px;
    font-family: "Cascadia Mono", "Consolas", monospace;
}

/* Multi-measure checklist (sparkline / box-plot / RAG participants) */
.kpg-checklist {
    border: 1px solid #e3e6ec;
    border-radius: 4px;
    max-height: 160px;
    overflow-y: auto;
    background: #ffffff;
    padding: 4px 0;
}
.kpg-checklist__item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 10px;
    font-size: 12px;
    color: #0f172a;
    cursor: pointer;
    user-select: none;
}
.kpg-checklist__item:hover { background: #f6f7f9; }
.kpg-checklist__item input { margin: 0; flex-shrink: 0; }
.kpg-checklist__item--anchor {
    background: rgba(29, 78, 216, 0.06);
    border-bottom: 1px solid #e3e6ec;
    cursor: default;
    font-weight: 600;
}
.kpg-checklist__tag {
    margin-left: auto;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--kpg-accent, #1d4ed8);
    background: rgba(29, 78, 216, 0.10);
    padding: 2px 7px;
    border-radius: 999px;
    flex-shrink: 0;
}

/* Buttons (dialog Apply/Cancel + mini Move ← / →) */
.kpg-btn {
    padding: 7px 18px;
    border-radius: 999px;
    border: 1px solid transparent;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.12s ease;
    min-width: 88px;
    font-family: inherit;
}
.kpg-btn--ghost {
    background: #ffffff;
    color: #0f172a;
    border-color: #e3e6ec;
}
.kpg-btn--ghost:hover { background: #f6f7f9; border-color: #cbd5e1; }
.kpg-btn--primary {
    background: #4361ee;
    color: #ffffff;
    border-color: #4361ee;
}
.kpg-btn--primary:hover { background: #3651d9; border-color: #3651d9; }
.kpg-btn--mini {
    padding: 4px 10px;
    font-size: 11px;
    min-width: 0;
    background: #ffffff;
    color: #0f172a;
    border: 1px solid #e3e6ec;
    font-weight: 500;
    border-radius: 4px;
    cursor: pointer;
    font-family: inherit;
}
.kpg-btn--mini:disabled { opacity: 0.4; cursor: not-allowed; }
.kpg-btn--reset { color: #94a3b8; }
.kpg-btn--reset:hover { color: #0f172a; }

/* Toast — "Copied N rows to clipboard" */
.kpg-toast {
    position: absolute;
    bottom: 50px;
    left: 50%;
    transform: translateX(-50%);
    background: #0f172a;
    color: #ffffff;
    padding: 8px 16px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 500;
    box-shadow: 0 6px 16px rgba(0,0,0,0.18);
    z-index: 50;
    pointer-events: none;
    transition: opacity 0.3s ease;
}
.kpg-toast--fade { opacity: 0; }

/* ─────────────────────────────────────────────────────────────────────────
 * v22 — Inline filters, row expand, saved views
 * ───────────────────────────────────────────────────────────────────────── */

/* Filter funnel button in each column header (next to the gear) */
.kpg-th__funnel {
    background: transparent;
    border: 0;
    color: var(--kpg-header-text, #ffffff);
    opacity: 0.55;
    padding: 2px 4px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    border-radius: 3px;
}
.kpg-th__funnel:hover { opacity: 1; background: rgba(0,0,0,0.12); }
.kpg-th__funnel--active { opacity: 1; color: #fcd34d; }

/* Filter popover — modal-ish but lighter than the configure dialog */
.kpg-filterpop {
    position: absolute;
    inset: 0;
    z-index: 35;
    background: rgba(15,23,42,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.kpg-filterpop__panel {
    background: #ffffff;
    border-radius: 8px;
    width: 100%;
    max-width: 340px;
    max-height: 80%;
    display: flex;
    flex-direction: column;
    box-shadow: 0 12px 32px rgba(15,23,42,0.22);
    overflow: hidden;
}
.kpg-filterpop__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    background: #f6f7f9;
    border-bottom: 1px solid #e3e6ec;
    font-size: 13px;
    font-weight: 600;
    color: #0f172a;
}
.kpg-filterpop__title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kpg-filterpop__close {
    background: transparent;
    border: 0;
    cursor: pointer;
    color: #94a3b8;
    font-size: 18px;
    line-height: 1;
    padding: 0 4px;
}
.kpg-filterpop__body {
    padding: 12px 14px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}
.kpg-filterpop__count {
    font-size: 11px;
    color: #94a3b8;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    font-weight: 600;
}
.kpg-filterpop__foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 14px;
    background: #f6f7f9;
    border-top: 1px solid #e3e6ec;
}

/* Row expand chevron in the identity cell — tracks body font so it's readable
   at any typography setting. The button's hit area sits ~30% larger than the
   glyph so it stays comfortably clickable. */
.kpg-id__chev {
    background: transparent;
    border: 0;
    color: #94a3b8;
    cursor: pointer;
    padding: 0;
    width:  calc(var(--kpg-body-fs, 13px) * 1.3);
    height: calc(var(--kpg-body-fs, 13px) * 1.3);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: var(--kpg-body-fs, 13px);
    font-weight: 600;
    line-height: 1;
    flex-shrink: 0;
    transition: color 0.12s ease;
}
.kpg-id__chev:hover { color: #0f172a; }
.kpg-id__chev--open { color: var(--kpg-accent, #1d4ed8); }

/* Detail panel rendered as a full-width <tr> below an expanded row */
.kpg-row--detail { cursor: default; }
.kpg-row--detail .kpg-td--detail {
    background: #f8fafc;
    border-bottom: 1px solid #cbd5e1;
    padding: 14px 18px 16px 38px;   /* indented under the chevron */
}
.kpg-detail__title {
    font-size: 14px;
    font-weight: 700;
    color: #0f172a;
    margin-bottom: 2px;
}
.kpg-detail__meta {
    font-size: 11px;
    color: #94a3b8;
    margin-bottom: 10px;
}
.kpg-detail__list {
    margin: 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 6px 24px;
}
.kpg-detail__list dt {
    font-size: 10.5px;
    font-weight: 600;
    color: #475569;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}
.kpg-detail__list dd {
    font-size: 12.5px;
    color: #0f172a;
    margin: 0 0 6px 0;
    font-variant-numeric: tabular-nums;
}

/* Saved views popover */
.kpg-views-pop {
    position: absolute;
    inset: 0;
    z-index: 35;
    background: rgba(15,23,42,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.kpg-views-pop__panel {
    background: #ffffff;
    border-radius: 8px;
    width: 100%;
    max-width: 380px;
    max-height: 80%;
    display: flex;
    flex-direction: column;
    box-shadow: 0 12px 32px rgba(15,23,42,0.22);
    overflow: hidden;
}
.kpg-views-pop__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    background: #f6f7f9;
    border-bottom: 1px solid #e3e6ec;
    font-size: 13px;
    font-weight: 600;
}
.kpg-views-pop__title { flex: 1; }
.kpg-views-pop__body {
    padding: 12px 14px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}
.kpg-views-list { display: flex; flex-direction: column; gap: 4px; margin-bottom: 10px; }
.kpg-views-list__row {
    display: flex;
    align-items: center;
    gap: 4px;
    border-radius: 4px;
    border: 1px solid #e3e6ec;
    background: #ffffff;
}
.kpg-views-list__row:hover { border-color: var(--kpg-accent, #1d4ed8); background: #f8fafc; }
.kpg-views-list__load {
    flex: 1;
    text-align: left;
    background: transparent;
    border: 0;
    padding: 8px 12px;
    cursor: pointer;
    font-size: 12.5px;
    color: #0f172a;
    font-weight: 600;
    border-radius: 4px;
    font-family: inherit;
}
.kpg-views-list__del {
    background: transparent;
    border: 0;
    color: #94a3b8;
    cursor: pointer;
    padding: 6px 10px;
    font-size: 16px;
    line-height: 1;
    border-radius: 50%;
}
.kpg-views-list__del:hover { color: #dc2626; background: rgba(220,38,38,0.08); }
.kpg-views-pop__save {
    display: flex;
    gap: 6px;
    padding-top: 8px;
    border-top: 1px solid #e3e6ec;
}
.kpg-views-pop__save .kpg-field__input { flex: 1; }
