content.css:
/* ========================================================================== */
/* BFUSION KPI Grid                                                           */
/* ========================================================================== */
.bfusion-root.kpg-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #ffffff;
  position: relative;
  color: #0f172a;
  padding-bottom: 24px;
  /* license badge clear-zone */
  --kpg-header-band: #8b1a2e;
  --kpg-header-text: #ffffff;
  --kpg-accent: #1d4ed8;
  --kpg-plan: #cbd5e1;
  --kpg-ok: #16a34a;
  --kpg-warn: #d97706;
  --kpg-risk: #dc2626;
  --kpg-header-fs: 12.5px;
  --kpg-body-fs: 13px;
}
.bfusion-root.kpg-root *,
.bfusion-root.kpg-root *:before,
.bfusion-root.kpg-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Shell + Board                                                              */
/* ========================================================================== */
.kpg-shell {
  position: absolute;
  inset: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
/* Classical flex chain with min-height: 0 everywhere — the body row grows to
 * fill remaining space and only the inner grid-wrap scrolls. */
.kpg-board {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  width: 100%;
  height: 100%;
}
.kpg-head {
  flex: 0 0 auto;
  min-width: 0;
}
.kpg-legendbar {
  flex: 0 0 auto;
  min-width: 0;
}
.kpg-strip {
  flex: 0 0 auto;
  min-width: 0;
}
.kpg-body {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.kpg-body {
  display: flex;
  flex-direction: row;
  align-items: stretch;
}
.kpg-main {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
/* ========================================================================== */
/* Header (title bar)                                                         */
/* ========================================================================== */
.kpg-head {
  background: #f6f7f9;
  border-bottom: 1px solid #e3e6ec;
  padding: 10px 14px;
}
.kpg-head__titlebar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
}
.kpg-head__titles {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.kpg-head__title {
  font-size: 15px;
  font-weight: 600;
  color: #0f172a;
  line-height: 1.2;
}
.kpg-head__subtitle {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 1px;
}
.kpg-head__status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  background: #ffffff;
  border: 1px solid #e3e6ec;
  font-size: 11px;
  font-weight: 500;
  color: #475569;
}
.kpg-head__status-text {
  white-space: nowrap;
}
.kpg-head__spacer {
  flex: 1;
}
/* Search box */
.kpg-search {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #ffffff;
  border: 1px solid #e3e6ec;
  border-radius: 4px;
  padding: 4px 10px;
  color: #94a3b8;
  font-size: var(--kpg-body-fs, 13px) !important;
  min-width: 220px;
  padding: 6px 12px;
}
.kpg-search input {
  border: 0;
  outline: 0;
  background: transparent;
  flex: 1;
  font-family: inherit;
  font-size: var(--kpg-body-fs, 13px) !important;
  line-height: 1.4;
  color: #0f172a;
  min-width: 0;
}
.kpg-search input::placeholder {
  color: #94a3b8;
  opacity: 1;
  font-size: inherit;
}
.kpg-search:focus-within {
  border-color: var(--kpg-header-band);
}
.kpg-search__icon {
  flex-shrink: 0;
}
.kpg-search__clear {
  border: 0;
  background: transparent;
  cursor: pointer;
  color: #94a3b8;
  font-size: 16px;
  line-height: 1;
  padding: 0 2px;
}
.kpg-search__clear:hover {
  color: #0f172a;
}
.kpg-info-btn {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid #e3e6ec;
  background: #ffffff;
  color: #475569;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
  padding: 0;
  flex-shrink: 0;
}
.kpg-info-btn:hover {
  border-color: var(--kpg-header-band);
  color: var(--kpg-header-band);
}
/* Square header chrome buttons (KPI toggle, future filter toggle, etc.) */
.kpg-head__iconbtn {
  width: 28px;
  height: 28px;
  border-radius: 4px;
  border: 1px solid #e3e6ec;
  background: #ffffff;
  color: #475569;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.12s ease;
  padding: 0;
  flex-shrink: 0;
  /* Pressed state — KPI tiles currently visible */
}
.kpg-head__iconbtn:hover {
  border-color: var(--kpg-header-band);
  color: var(--kpg-header-band);
  background: #ffffff;
}
.kpg-head__iconbtn.kpg-head__iconbtn--active {
  background: rgba(139, 26, 46, 0.08);
  border-color: var(--kpg-header-band);
  color: var(--kpg-header-band);
}
.kpg-head__iconbtn svg {
  display: block;
}
.kpg-info-btn__i {
  font-family: Georgia, "Times New Roman", serif;
  font-style: italic;
  font-weight: 700;
  font-size: 13px;
  line-height: 1;
}
/* ========================================================================== */
/* KPI Strip (optional)                                                       */
/* ========================================================================== */
.kpg-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid #e3e6ec;
  background: #ffffff;
}
.kpg-tile {
  background: #ffffff;
  border: 1px solid #e3e6ec;
  border-top: 3px solid var(--tile-accent, var(--kpg-accent));
  border-radius: 8px;
  padding: 10px 12px;
  min-width: 0;
  position: relative;
}
.kpg-tile:hover {
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.06);
}
.kpg-tile:hover .kpg-tile__gear {
  opacity: 1;
}
.kpg-tile__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 4px;
}
.kpg-tile__label {
  font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.48));
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}
.kpg-tile__gear {
  background: transparent;
  border: 0;
  padding: 2px;
  color: #94a3b8;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.12s ease, color 0.12s ease;
  border-radius: 3px;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.kpg-tile__gear:hover {
  color: var(--kpg-header-band);
  background: rgba(139, 26, 46, 0.08);
  opacity: 1;
}
.kpg-tile__gear svg {
  display: block;
}
.kpg-tile__value {
  font-size: var(--kpg-kpi-fs, 22px);
  font-weight: 700;
  line-height: 1.1;
  color: var(--tile-accent, #0f172a);
  letter-spacing: -0.3px;
  font-variant-numeric: tabular-nums;
}
.kpg-tile__trend {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
}
.kpg-tile__trend .kpg-spark-bar,
.kpg-tile__trend .kpg-spark-line {
  flex: 1;
  min-width: 0;
}
.kpg-tile__delta {
  font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.5));
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: #475569;
}
.kpg-tile__delta--ok {
  color: var(--kpg-ok);
}
.kpg-tile__delta--warn {
  color: var(--kpg-warn);
}
.kpg-tile__delta--risk {
  color: var(--kpg-risk);
}
.kpg-tile__delta--neutral {
  color: #475569;
}
.kpg-tile__sub {
  font-size: max(10px, calc(var(--kpg-kpi-fs, 22px) * 0.48));
  color: #94a3b8;
  margin-top: 4px;
}
/* When a tile shows a sparkline + delta the value is slightly compressed to
   leave room for the trend row. ~91% of the configured KPI font-size. */
.kpg-tile--withtrend .kpg-tile__value {
  font-size: calc(var(--kpg-kpi-fs, 22px) * 0.91);
}
/* ========================================================================== */
/* Grid                                                                       */
/* ========================================================================== */
.kpg-grid-wrap {
  overflow: auto;
  flex: 1 1 0;
  min-height: 0;
  /* allow shrinking below content */
  background: #ffffff;
  /* Force visible scrollbars (Power BI iframe + Windows hide them otherwise) */
  scrollbar-width: thin;
  scrollbar-color: #cbd5e1 #f1f5f9;
}
.kpg-grid-wrap::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.kpg-grid-wrap::-webkit-scrollbar-track {
  background: #f1f5f9;
}
.kpg-grid-wrap::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 6px;
  border: 2px solid #f1f5f9;
}
.kpg-grid-wrap::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}
.kpg-grid-wrap::-webkit-scrollbar-corner {
  background: #f1f5f9;
}
.kpg-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: var(--kpg-body-fs, 13px);
  color: #0f172a;
}
/* Dark red column-header band */
.kpg-th {
  text-align: left;
  background: var(--kpg-header-band);
  color: var(--kpg-header-text);
  font-size: var(--kpg-header-fs, 12.5px);
  font-weight: 600;
  padding: 12px 14px;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
  position: sticky;
  top: 0;
  z-index: 3;
  white-space: nowrap;
  cursor: default;
  user-select: none;
  /* While being dragged for reorder */
  /* Hover over a drop target during drag */
  /* Draggable headers get a subtle move cursor on hover (everywhere except the
     * inner buttons and the right-edge resize strip). */
}
.kpg-th[data-action="sort"] {
  cursor: pointer;
}
.kpg-th[data-action="sort"]:hover {
  background: rgba(0, 0, 0, 0.1);
}
.kpg-th.kpg-th--dragging {
  opacity: 0.4;
  cursor: grabbing;
}
.kpg-th.kpg-th--drop-target {
  box-shadow: inset 4px 0 0 0 var(--kpg-accent, #1d4ed8);
}
.kpg-th[draggable="true"] {
  cursor: move;
}
/* Resize handle along the right edge of every column header */
.kpg-th__resize {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 6px;
  cursor: col-resize;
  z-index: 5;
  background: transparent;
  transition: background 0.1s ease;
}
.kpg-th__resize:hover {
  background: rgba(255, 255, 255, 0.35);
}
.kpg-th--right {
  text-align: right;
}
.kpg-th--center {
  text-align: center;
}
.kpg-th--frozen {
  position: sticky;
  left: 0;
  z-index: 4;
  background: var(--kpg-header-band);
  color: var(--kpg-header-text);
  /* No min-width here — width is driven by the <colgroup>/inline width on the
     * <col> element so the user's ⚙ → "Column Width (px)" override always wins.
     * The default-when-blank is set in renderGrid (240px for the row column). */
}
.kpg-th__inner {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.kpg-th__sortbtn {
  background: transparent;
  border: 0;
  color: inherit;
  padding: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: inherit;
}
.kpg-th__sortbtn:hover .kpg-th__label {
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.5);
}
.kpg-th__label {
  display: inline-block;
}
.kpg-th__sort {
  color: var(--kpg-header-text);
  opacity: 0.75;
  font-size: 9px;
}
.kpg-th__gear {
  background: transparent;
  border: 0;
  color: var(--kpg-header-text);
  opacity: 0.65;
  padding: 2px 4px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  border-radius: 3px;
  transition: background 0.12s ease, opacity 0.12s ease;
}
.kpg-th__gear:hover {
  opacity: 1;
  background: rgba(0, 0, 0, 0.12);
}
.kpg-th__gear svg {
  display: block;
}
.kpg-td {
  padding: 11px 14px;
  border-bottom: 1px solid #eef0f4;
  vertical-align: middle;
  background: #ffffff;
  white-space: nowrap;
}
.kpg-td--right {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.kpg-td--center {
  text-align: center;
}
.kpg-td--frozen {
  position: sticky;
  left: 0;
  z-index: 1;
  background: #ffffff;
  /* Width driven by <col> in colgroup — see note on .kpg-th--frozen */
}
.kpg-grid--striped tbody .kpg-row:nth-of-type(even) .kpg-td {
  background: #fafbfc;
}
.kpg-grid--striped tbody .kpg-row:nth-of-type(even) .kpg-td--frozen {
  background: #fafbfc;
}
/* Compact mode is about ROW HEIGHT only — keep body font-size from the typography
 * variable so the user's --kpg-body-fs choice still applies. */
.kpg-grid--compact .kpg-td {
  padding: 6px 14px;
}
.kpg-grid--compact .kpg-th {
  padding: 8px 14px;
}
.kpg-row {
  cursor: pointer;
  transition: background 0.1s ease;
  /* Keyboard focus ring — visible only when reached via keyboard, not on mouse click.
     * AppSource Keyboard Navigation requirement: focus must be perceptible. */
  /* suppress the default UA focus when not :focus-visible */
}
.kpg-row:hover .kpg-td {
  background: #f3f7ff;
}
.kpg-row:hover .kpg-td--frozen {
  background: #f3f7ff;
}
.kpg-row:focus-visible {
  outline: 2px solid var(--kpg-accent, #1d4ed8);
  outline-offset: -2px;
}
.kpg-row:focus {
  outline: 0;
}
.kpg-row--selected .kpg-td,
.kpg-row--selected .kpg-td--frozen {
  background: #dbeafe !important;
}
/* Group header bar (when "Group rows by this column" is on) */
.kpg-row--group {
  cursor: pointer;
  /* click to toggle collapse */
  user-select: none;
}
.kpg-row--group .kpg-td--group {
  background: #f1f5f9;
  border-top: 1px solid #cbd5e1;
  border-bottom: 1px solid #cbd5e1;
  padding: 8px 14px;
  /* font-size inherited from --kpg-body-fs via the table */
  position: sticky;
  left: 0;
  z-index: 1;
}
.kpg-row--group:hover .kpg-td--group {
  background: #e6eaf0;
}
/* Depth-based indentation. Group headers carry the depth signal through
 * indentation + font weight + chevron color. Subtotals carry it through
 * dedicated per-depth background fills (customizable via format pane). */
/* blue */
/* fuchsia */
/* cyan */
.kpg-td--group-depth-0 {
  padding-left: 14px;
  font-weight: 700;
}
.kpg-td--group-depth-1 {
  padding-left: 36px;
  font-weight: 600;
}
.kpg-td--group-depth-2 {
  padding-left: 58px;
  font-weight: 500;
}
/* Chevron color signals depth at a glance — especially useful when the user
 * collapses groups and only chevrons remain. */
.kpg-row--group-depth-0 .kpg-group__chev {
  color: #1d4ed8;
}
.kpg-row--group-depth-1 .kpg-group__chev {
  color: #c026d3;
}
.kpg-row--group-depth-2 .kpg-group__chev {
  color: #0891b2;
}
/* Subtotal rows — full-width depth-colored background. Each level's color is
 * driven by a CSS variable so the user can override in the format pane Colors
 * card without touching code. Borders are kept subtle so the colored fill is
 * the primary depth signal (no extra rails / lines competing with it). */
.kpg-row--subtotal-depth-0 .kpg-td--subtotal,
.kpg-row--subtotal-depth-0 .kpg-td--subtotal.kpg-td--frozen {
  background: var(--kpg-subtotal-bg-0, #e0f2fe) !important;
}
.kpg-row--subtotal-depth-1 .kpg-td--subtotal,
.kpg-row--subtotal-depth-1 .kpg-td--subtotal.kpg-td--frozen {
  background: var(--kpg-subtotal-bg-1, #fae8ff) !important;
}
.kpg-row--subtotal-depth-2 .kpg-td--subtotal,
.kpg-row--subtotal-depth-2 .kpg-td--subtotal.kpg-td--frozen {
  background: var(--kpg-subtotal-bg-2, #d1fae5) !important;
}
.kpg-td--subtotal-depth-0 {
  border-top: 1px solid rgba(0, 0, 0, 0.1);
  padding: 9px 14px;
}
.kpg-td--subtotal-depth-1 {
  padding-left: 36px;
  padding-top: 7px;
  padding-bottom: 7px;
  font-size: 0.95em;
}
.kpg-td--subtotal-depth-2 {
  padding-left: 58px;
  padding-top: 5px;
  padding-bottom: 5px;
  font-size: 0.92em;
  font-style: italic;
}
.kpg-row--group-collapsed .kpg-td--group {
  border-bottom-color: transparent;
  /* visually merges with following subtotal row */
}
.kpg-row--group-ok .kpg-td--group {
  background: #ecfdf5;
  border-color: #bbf7d0;
}
.kpg-row--group-warn .kpg-td--group {
  background: #fffbeb;
  border-color: #fde68a;
}
.kpg-row--group-risk .kpg-td--group {
  background: #fef2f2;
  border-color: #fecaca;
}
.kpg-row--group-ok:hover .kpg-td--group {
  background: #d8f6e6;
}
.kpg-row--group-warn:hover .kpg-td--group {
  background: #fdf3d6;
}
.kpg-row--group-risk:hover .kpg-td--group {
  background: #fbe2e2;
}
.kpg-group__chev {
  display: inline-block;
  width: calc(var(--kpg-body-fs, 13px) * 1.1);
  margin-right: 6px;
  font-size: var(--kpg-body-fs, 13px);
  font-weight: 600;
  color: #475569;
  vertical-align: middle;
  transition: transform 0.12s ease;
}
.kpg-group__dot {
  display: inline-block;
  width: calc(var(--kpg-body-fs, 13px) - 3px);
  height: calc(var(--kpg-body-fs, 13px) - 3px);
  border-radius: 50%;
  margin-right: 8px;
  vertical-align: middle;
}
.kpg-group__label {
  color: #475569;
  font-weight: 600;
}
.kpg-group__key {
  font-weight: 700;
  color: #0f172a;
}
.kpg-row--subtotal {
  cursor: default;
}
.kpg-row--subtotal .kpg-td--subtotal {
  background: #f8fafc;
  border-bottom: 1px solid #cbd5e1;
  font-weight: 600;
  color: #0f172a;
  /* font-size inherited from --kpg-body-fs */
}
.kpg-subtotal__lbl {
  color: #94a3b8;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  font-size: 10.5px;
}
.kpg-subtotal__count {
  color: #94a3b8;
  font-weight: 500;
  margin-left: 8px;
  font-size: 11px;
}
/* Pinned Grand Total row — strongest visual emphasis. User-customizable bg via
 * --kpg-grand-total-bg (format pane Colors card → "Grand Total — Background"). */
.kpg-row--totals .kpg-td,
.kpg-row--totals .kpg-td--frozen {
  background: var(--kpg-grand-total-bg, #f3f4f6) !important;
  font-weight: 700;
  border-top: 2px solid rgba(0, 0, 0, 0.15);
  border-bottom: 2px solid rgba(0, 0, 0, 0.15);
}
.kpg-row--totals {
  cursor: default;
  /* Background, font-weight and borders come from the .kpg-row--totals .kpg-td
     * rule above (driven by --kpg-grand-total-bg). Only style overrides here. */
}
.kpg-row--totals .kpg-td {
  color: #0f172a;
}
.kpg-row--totals-top .kpg-td {
  position: sticky;
  top: 44px;
  /* below the sticky header */
  z-index: 2;
  border-top: 0;
  border-bottom: 2px solid var(--kpg-header-band);
}
.kpg-row--totals-top .kpg-td--frozen {
  z-index: 3;
}
.kpg-totals-label {
  font-weight: 700;
}
.kpg-totals-sub {
  display: block;
  font-size: 10.5px;
  color: #94a3b8;
  font-weight: 400;
  margin-top: 1px;
}
/* Identity cell */
.kpg-id {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 200px;
  white-space: normal;
}
.kpg-id__text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.kpg-id__name {
  font-weight: 600;
  color: #0f172a;
  line-height: 1.25;
}
.kpg-id__meta {
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
  color: #94a3b8;
  margin-top: 1px;
}
/* Row-expand chevron in the identity cell — tracks body font. The LESS file
   was previously missing this rule entirely (only embeddedCss.ts had it
   hardcoded at 9px), which is why bumping --kpg-body-fs in the format pane
   never grew the chevron. Now both stylesheets agree. */
.kpg-id__chev {
  background: transparent;
  border: 0;
  color: #94a3b8;
  cursor: pointer;
  padding: 0;
  width: calc(var(--kpg-body-fs, 13px) * 1.3);
  height: calc(var(--kpg-body-fs, 13px) * 1.3);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--kpg-body-fs, 13px);
  font-weight: 600;
  line-height: 1;
  flex-shrink: 0;
  transition: color 0.12s ease;
}
.kpg-id__chev:hover {
  color: #0f172a;
}
.kpg-id__chev--open {
  color: var(--kpg-accent);
}
.kpg-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
  display: inline-block;
  background: #94a3b8;
}
.kpg-dot--ok {
  background: var(--kpg-ok);
}
.kpg-dot--warn {
  background: var(--kpg-warn);
}
.kpg-dot--risk {
  background: var(--kpg-risk);
}
.kpg-dot--neutral {
  background: #94a3b8;
}
.kpg-null {
  color: #94a3b8;
}
/* ── Scalar cell renderers ─────────────────────────────────────────── */
.kpg-num {
  font-variant-numeric: tabular-nums;
}
.kpg-num--zero {
  color: #94a3b8;
  /* de-emphasize 0 values so signal-bearing rows stand out */
  opacity: 0.55;
}
/* Heat-map cells: when a cell carries its own background via cellStyle, we
 * darken slightly on row hover (instead of overriding the bg). The striped-row
 * background also needs to step aside so the gradient shows through. */
.kpg-td--heat {
  transition: filter 0.1s ease;
}
.kpg-grid--striped tbody .kpg-row:nth-of-type(even) .kpg-td--heat {
  /* keep heat color, the inline style wins anyway */
}
.kpg-row:hover .kpg-td--heat {
  filter: brightness(0.94);
}
.kpg-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 10px 2px 6px;
  border-radius: 999px;
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
  font-weight: 600;
  border: 1px solid transparent;
  line-height: 1.4;
}
.kpg-pill__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(var(--kpg-body-fs, 13px) + 1px);
  height: calc(var(--kpg-body-fs, 13px) + 1px);
  border-radius: 50%;
  font-size: calc(var(--kpg-body-fs, 13px) - 4px);
  font-weight: 700;
  color: #ffffff;
  flex-shrink: 0;
  line-height: 1;
}
.kpg-pill__text {
  white-space: nowrap;
}
.kpg-pill--ok {
  background: #ecfdf5;
  color: #059669;
  border-color: #bbf7d0;
}
.kpg-pill--ok .kpg-pill__icon {
  background: #059669;
}
.kpg-pill--warn {
  background: #fffbeb;
  color: #d97706;
  border-color: #fde68a;
}
.kpg-pill--warn .kpg-pill__icon {
  background: #d97706;
}
.kpg-pill--risk {
  background: #fef2f2;
  color: #dc2626;
  border-color: #fecaca;
}
.kpg-pill--risk .kpg-pill__icon {
  background: #dc2626;
}
.kpg-pill--neutral {
  background: #f1f5f9;
  color: #64748b;
  border-color: #e2e8f0;
}
.kpg-pill--neutral .kpg-pill__icon {
  background: #94a3b8;
}
/* Stacked count chips on group subtotal + Grand Total rows for status-pill
   columns: ✓3 ⚠2 ✗1. Keeps collapsed groups informative without bleeding
   into adjacent cells (some pill columns are narrow).
   Background contrast tuned so chips read clearly against the subtotal-blue
   (#e0f2fe), grand-total-grey (#f3f4f6), and plain row backgrounds. */
.kpg-rollup-grp {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  flex-wrap: nowrap;
  max-width: 100%;
  overflow: hidden;
  vertical-align: middle;
}
.kpg-rollup {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 1px 7px;
  min-height: calc(var(--kpg-body-fs, 13px) + 4px);
  border-radius: 999px;
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  flex-shrink: 0;
  border: 1px solid transparent;
}
.kpg-rollup--ok {
  background: #d1fae5;
  color: #047857;
  border-color: #6ee7b7;
}
.kpg-rollup--warn {
  background: #fef3c7;
  color: #b45309;
  border-color: #fcd34d;
}
.kpg-rollup--risk {
  background: #fee2e2;
  color: #b91c1c;
  border-color: #fca5a5;
}
/* ========================================================================== */
/* Chrome scaling — buttons, icons, gears, sort arrows, legend                */
/* All visual chrome tracks --kpg-body-fs / --kpg-header-fs so the user's     */
/* typography setting in the format pane flows through to every affordance.  */
/* Data-cell SVGs (sparklines, box plots) are explicitly excluded — those     */
/* have their own viewBox-based sizing.                                       */
/* ========================================================================== */
/* Square icon buttons in the visual header (KPI toggle, etc.) — size + icon
   scale with header font; padding stays compact. */
.kpg-head__iconbtn {
  width: calc(var(--kpg-header-fs, 12.5px) * 2.2);
  height: calc(var(--kpg-header-fs, 12.5px) * 2.2);
}
.kpg-head__iconbtn svg {
  width: calc(var(--kpg-header-fs, 12.5px) * 1.1);
  height: calc(var(--kpg-header-fs, 12.5px) * 1.1);
}
.kpg-info-btn {
  width: calc(var(--kpg-header-fs, 12.5px) * 1.9);
  height: calc(var(--kpg-header-fs, 12.5px) * 1.9);
}
.kpg-info-btn__i {
  font-size: calc(var(--kpg-header-fs, 12.5px) * 1.05);
}
.kpg-search__icon {
  width: calc(var(--kpg-header-fs, 12.5px) * 1);
  height: calc(var(--kpg-header-fs, 12.5px) * 1);
}
/* Column-header sort arrow + gear — scale with the header band font.
   Arrows tracked at ~90% of the header text so the indicator is clearly
   visible at any typography setting. */
.kpg-th__sort {
  font-size: calc(var(--kpg-header-fs, 12.5px) * 0.9);
  opacity: 0.85;
}
.kpg-th__gear svg {
  width: calc(var(--kpg-header-fs, 12.5px) * 1);
  height: calc(var(--kpg-header-fs, 12.5px) * 1);
}
/* Column-header filter button (funnel icon) — same scaling. */
.kpg-th__filter svg,
.kpg-th__filter--active svg {
  width: calc(var(--kpg-header-fs, 12.5px) * 0.9);
  height: calc(var(--kpg-header-fs, 12.5px) * 0.9);
}
/* Legend bar — bottom strip with status dots + Actual/Plan + groupings.
   Text + buttons + dots all track the body font. */
.kpg-legendbar {
  font-size: calc(var(--kpg-body-fs, 13px) - 1.5px);
}
.kpg-legend__copybtn {
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
}
.kpg-legend__copybtn svg {
  width: calc(var(--kpg-body-fs, 13px) - 1px);
  height: calc(var(--kpg-body-fs, 13px) - 1px);
}
.kpg-grouped-by {
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
}
/* Mini buttons (Save view, Expand all, Collapse all, etc.) — track body font. */
.kpg-btn--mini {
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
}
.kpg-btn--mini svg {
  width: calc(var(--kpg-body-fs, 13px) - 1px);
  height: calc(var(--kpg-body-fs, 13px) - 1px);
}
/* Inline-bar cell: gradient is set on the <td> via inline style; this rule
   only ensures the gradient is painted against the cell box, not bleeding
   under borders, and isolates it from row-hover so the bar stays visible. */
.kpg-td {
  background-clip: padding-box;
}
/* RAG composite — a row of small status dots, hover reveals the breakdown */
.kpg-rag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 2px;
  cursor: help;
}
.kpg-rag__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #94a3b8;
  box-shadow: 0 0 0 1.5px #ffffff inset;
  flex-shrink: 0;
}
.kpg-rag__dot.kpg-dot--ok {
  background: var(--kpg-ok);
}
.kpg-rag__dot.kpg-dot--warn {
  background: var(--kpg-warn);
}
.kpg-rag__dot.kpg-dot--risk {
  background: var(--kpg-risk);
}
.kpg-rag__dot.kpg-dot--neutral {
  background: #94a3b8;
}
/* Subtotal/Portfolio Totals RAG: per-tone count pills */
.kpg-rag__count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  padding: 0 5px;
  height: 16px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  margin-right: 3px;
}
.kpg-rag__count--ok {
  background: #ecfdf5;
  color: #059669;
  border: 1px solid #bbf7d0;
}
.kpg-rag__count--warn {
  background: #fffbeb;
  color: #d97706;
  border: 1px solid #fde68a;
}
.kpg-rag__count--risk {
  background: #fef2f2;
  color: #dc2626;
  border: 1px solid #fecaca;
}
.kpg-prog {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 120px;
  justify-content: flex-end;
}
.kpg-prog__bar {
  flex: 1;
  height: 8px;
  background: #eef1f4;
  border-radius: 4px;
  overflow: hidden;
  min-width: 60px;
  max-width: 140px;
}
.kpg-prog__bar span {
  display: block;
  height: 100%;
  border-radius: 4px;
  transition: width 0.3s ease;
}
.kpg-prog__val {
  font-size: 11.5px;
  color: #475569;
  font-variant-numeric: tabular-nums;
  min-width: 40px;
  text-align: right;
}
.kpg-var {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.kpg-var__arrow {
  font-size: 11px;
}
.kpg-var--pos {
  color: #16a34a;
}
/* negative variance = under = good (cost convention) */
.kpg-var--neg {
  color: #dc2626;
}
/* positive variance = over = bad */
.kpg-var--flat {
  color: #94a3b8;
}
.kpg-date {
  color: #475569;
  font-variant-numeric: tabular-nums;
}
/* ── Mini-charts ───────────────────────────────────────────────────── */
/* Bullet chart */
.kpg-bullet-cell {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 280px;
}
.kpg-bullet-val {
  font-variant-numeric: tabular-nums;
  color: #0f172a;
  min-width: 90px;
}
.kpg-bullet {
  position: relative;
  display: inline-block;
  width: 180px;
  height: 18px;
  flex-shrink: 0;
}
.kpg-bullet__range {
  position: absolute;
  inset: 4px 0;
  background: #e5e7eb;
  border-radius: 2px;
}
.kpg-bullet__actual {
  position: absolute;
  top: 6px;
  left: 0;
  height: 10px;
  background: #1e3a8a;
  /* dark navy */
  border-radius: 1px;
  transition: width 0.3s ease;
}
.kpg-bullet__actual--over {
  background: var(--kpg-risk);
}
.kpg-bullet__target {
  position: absolute;
  top: 2px;
  bottom: 2px;
  width: 2px;
  background: #0f172a;
}
/* Bar sparkline */
.kpg-spark-bar {
  display: inline-block;
  vertical-align: middle;
  width: 130px;
  height: 32px;
  overflow: hidden;
  /* safety: clip any rounding overflow inside the SVG */
}
.kpg-spark-bar svg {
  display: block;
  width: 100%;
  height: 100%;
}
/* Line sparkline */
.kpg-spark-line {
  display: inline-block;
  vertical-align: middle;
  width: 130px;
  height: 32px;
  overflow: hidden;
}
.kpg-spark-line svg {
  display: block;
  width: 100%;
  height: 100%;
}
.kpg-spark-line path {
  fill: none;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.kpg-spark-line path.kpg-spark-line__actual {
  stroke-width: 1.7;
}
.kpg-spark-line path.kpg-spark-line__plan {
  stroke-width: 1.5;
}
/* Box plot */
.kpg-boxplot {
  display: inline-block;
  vertical-align: middle;
  width: 150px;
  height: 28px;
}
.kpg-boxplot svg {
  display: block;
}
/* ========================================================================== */
/* Insight Rail (secondary; default collapsed)                                */
/* ========================================================================== */
.kpg-rail {
  flex: 0 0 240px;
  background: #f6f7f9;
  border-left: 1px solid #e3e6ec;
  padding: 10px 12px 12px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
}
.kpg-rail--collapsed {
  flex: 0 0 16px;
  padding: 8px 0 0;
  cursor: pointer;
  background: linear-gradient(180deg, #f6f7f9 0%, #eef0f4 100%);
  border-left: 1px solid #e3e6ec;
  display: flex;
  align-items: flex-start;
  /* arrow at the top, not vertically centered */
  justify-content: center;
}
.kpg-rail--collapsed:hover {
  background: #eef0f4;
}
/* Insight rail — every text + icon element tracks --kpg-body-fs so the rail
   stays readable when the user bumps grid typography. */
.kpg-rail__arrow {
  color: #94a3b8;
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
  line-height: 1;
}
.kpg-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.kpg-rail__title {
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #475569;
}
.kpg-rail__toggle {
  width: calc(var(--kpg-body-fs, 13px) + 5px);
  height: calc(var(--kpg-body-fs, 13px) + 5px);
  border-radius: 4px;
  border: 0;
  background: transparent;
  color: #94a3b8;
  font-size: calc(var(--kpg-body-fs, 13px) - 3px);
  cursor: pointer;
  padding: 0;
}
.kpg-rail__toggle:hover {
  color: var(--kpg-header-band);
  background: rgba(139, 26, 46, 0.08);
}
.kpg-rail__divider {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed #e3e6ec;
  font-size: calc(var(--kpg-body-fs, 13px) - 3px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #94a3b8;
  margin-bottom: 6px;
}
.kpg-rail__group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.kpg-insight {
  display: flex;
  flex-direction: row;
  gap: 8px;
  padding: 8px 10px;
  background: #ffffff;
  border-radius: 6px;
  border-left: 3px solid #e3e6ec;
}
.kpg-insight--info {
  border-left-color: #3b82f6;
}
.kpg-insight--success {
  border-left-color: var(--kpg-ok);
}
.kpg-insight--warning {
  border-left-color: var(--kpg-warn);
}
.kpg-insight--critical {
  border-left-color: var(--kpg-risk);
}
.kpg-insight__icon {
  width: calc(var(--kpg-body-fs, 13px) + 9px);
  height: calc(var(--kpg-body-fs, 13px) + 9px);
  border-radius: 50%;
  background: #f6f7f9;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: calc(var(--kpg-body-fs, 13px) - 1px);
  font-weight: 700;
  color: #0f172a;
  flex-shrink: 0;
}
.kpg-insight__body {
  min-width: 0;
  flex: 1;
}
.kpg-insight__label {
  font-size: calc(var(--kpg-body-fs, 13px) - 2.5px);
  font-weight: 700;
  color: #0f172a;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.kpg-insight__text {
  font-size: calc(var(--kpg-body-fs, 13px) - 2px);
  color: #475569;
  line-height: 1.4;
  margin-top: 2px;
}
/* ========================================================================== */
/* Footer legend                                                              */
/* ========================================================================== */
.kpg-legendbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 16px;
  border-bottom: 1px solid #e3e6ec;
  background: #fbfbfd;
  font-size: 11.5px;
  color: #94a3b8;
}
.kpg-legend {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}
.kpg-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.kpg-legend__sep {
  color: #cbd5e1;
  margin: 0 4px;
}
.kpg-legend__line {
  display: inline-block;
  width: 18px;
  height: 0;
  border-top: 2px solid var(--kpg-accent);
  vertical-align: middle;
}
.kpg-legend__line--plan {
  border-top-style: dashed;
  border-top-width: 1.5px;
  border-top-color: var(--kpg-plan);
}
.kpg-legend__refresh {
  white-space: nowrap;
}
/* "Grouped by: A › B" chip — the only way to remove a grouping level when the
 * grouped column itself has been hidden from the grid header. */
.kpg-grouped-by {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
}
.kpg-grouped-by__label {
  color: #475569;
  font-weight: 600;
  margin-right: 4px;
}
.kpg-grouped-by__sep {
  color: #94a3b8;
  margin: 0 2px;
}
.kpg-grouped-by__chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 3px 1px 8px;
  border-radius: 999px;
  background: #f1f5f9;
  color: #0f172a;
  border: 1px solid #e3e6ec;
  font-weight: 600;
  line-height: 1.5;
}
.kpg-grouped-by__chip--depth-0 {
  border-left: 3px solid #1d4ed8;
  padding-left: 6px;
}
.kpg-grouped-by__chip--depth-1 {
  border-left: 3px solid #c026d3;
  padding-left: 6px;
}
.kpg-grouped-by__chip--depth-2 {
  border-left: 3px solid #0891b2;
  padding-left: 6px;
}
.kpg-grouped-by__name {
  font-weight: 600;
}
.kpg-grouped-by__x {
  background: transparent;
  border: 0;
  color: #94a3b8;
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 50%;
}
.kpg-grouped-by__x:hover {
  color: #0f172a;
  background: rgba(15, 23, 42, 0.08);
}
.kpg-legend__right {
  display: inline-flex;
  align-items: center;
  gap: 14px;
}
.kpg-legend__copybtn {
  background: #ffffff;
  border: 1px solid #e3e6ec;
  border-radius: 4px;
  padding: 3px 9px;
  font-size: 11px;
  color: #475569;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: inherit;
  transition: all 0.12s ease;
}
.kpg-legend__copybtn:hover {
  color: #0f172a;
  border-color: #cbd5e1;
  background: #fff;
}
.kpg-legend__copybtn:active {
  transform: translateY(0.5px);
}
.kpg-legend__copybtn svg {
  display: block;
}
.kpg-legend__copylabel {
  font-weight: 500;
}
/* Transient toast for "Copied N rows to clipboard" */
.kpg-toast {
  position: absolute;
  bottom: 50px;
  left: 50%;
  transform: translateX(-50%);
  background: #0f172a;
  color: #ffffff;
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.18);
  z-index: 50;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.kpg-toast--fade {
  opacity: 0;
}
/* ========================================================================== */
/* Info Popover                                                               */
/* ========================================================================== */
.kpg-info-pop {
  position: absolute;
  inset: 0;
  display: none;
  z-index: 30;
  background: rgba(15, 23, 42, 0.18);
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.kpg-info-pop[data-state="shown"] {
  display: flex;
}
.kpg-info-pop__inner {
  background: #ffffff;
  border-radius: 10px;
  max-width: 420px;
  width: 100%;
  padding: 18px 22px 20px;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.2);
  position: relative;
  max-height: 86%;
  overflow-y: auto;
}
.kpg-info-pop__close {
  position: absolute;
  top: 8px;
  right: 10px;
  border: 0;
  background: transparent;
  font-size: 18px;
  cursor: pointer;
  color: #94a3b8;
  line-height: 1;
  padding: 4px 6px;
}
.kpg-info-pop__close:hover {
  color: #0f172a;
}
.kpg-info-pop__title {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  padding-bottom: 6px;
  border-bottom: 2px solid #E8612A;
  margin-bottom: 10px;
}
.kpg-info-pop__desc {
  font-size: 12px;
  color: #475569;
  line-height: 1.5;
  margin-bottom: 12px;
}
.kpg-info-pop__subhead {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.kpg-info-pop__list {
  margin: 0;
  padding-left: 18px;
}
.kpg-info-pop__list li {
  font-size: 11.5px;
  color: #475569;
  line-height: 1.5;
  margin-bottom: 4px;
}
/* ========================================================================== */
/* Responsive breakpoints                                                     */
/* ========================================================================== */
.kpg-root.kpg-medium .kpg-strip {
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
}
.kpg-root.kpg-medium .kpg-rail {
  flex-basis: 200px;
}
.kpg-root.kpg-medium .kpg-bullet {
  width: 140px;
}
.kpg-root.kpg-medium .kpg-spark-bar,
.kpg-root.kpg-medium .kpg-spark-line {
  width: 110px;
}
.kpg-root.kpg-medium .kpg-boxplot {
  width: 130px;
}
.kpg-root.kpg-narrow {
  padding-bottom: 28px;
}
.kpg-root.kpg-narrow .kpg-body {
  flex-direction: column;
}
.kpg-root.kpg-narrow .kpg-strip {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.kpg-root.kpg-narrow .kpg-rail {
  flex-basis: auto;
  border-left: 0;
  border-top: 1px solid #e3e6ec;
}
.kpg-root.kpg-narrow .kpg-rail.kpg-rail--collapsed {
  border-top: 1px solid #e3e6ec;
  flex-basis: 16px;
}
.kpg-root.kpg-narrow .kpg-search {
  min-width: 140px;
}
.kpg-root.kpg-narrow .kpg-bullet {
  width: 100px;
}
.kpg-root.kpg-narrow .kpg-spark-bar,
.kpg-root.kpg-narrow .kpg-spark-line {
  width: 80px;
}
.kpg-root.kpg-narrow .kpg-boxplot {
  width: 100px;
}
.kpg-root.kpg-narrow .kpg-prog {
  min-width: 80px;
}
.kpg-root.kpg-narrow .kpg-prog__bar {
  max-width: 70px;
}
/* ========================================================================== */
/* Landing page                                                               */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 460px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge                                                              */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State                                                           */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
/* ========================================================================== */
/* High-contrast mode (Windows HC; driven by host.colorPalette.isHighContrast) */
/* ========================================================================== */
.bfusion-root--hc {
  /* Theme colors are pushed into CSS vars by applyThemeDefaults(); these
     * rules reshape the visual to use outlines rather than fills so detail
     * survives a stark FG/BG palette. */
  background: var(--kpg-bg-panel, #000) !important;
  color: var(--kpg-text-strong, #fff) !important;
  /* Striping disabled in HC — backgrounds carry meaning, stripes are noise */
  /* Heat-map cells: disable the pastel gradient in HC. The user-set inline
     * style on the td would otherwise leak a low-contrast color. */
}
.bfusion-root--hc .kpg-grid-wrap,
.bfusion-root--hc .kpg-tile,
.bfusion-root--hc .kpg-strip,
.bfusion-root--hc .kpg-head,
.bfusion-root--hc .kpg-legendbar,
.bfusion-root--hc .kpg-rail,
.bfusion-root--hc .kpg-dialog__panel {
  background: var(--kpg-bg-panel, #000) !important;
  color: var(--kpg-text-strong, #fff) !important;
}
.bfusion-root--hc .kpg-tile {
  border: 2px solid var(--kpg-text-strong, #fff) !important;
  border-top-color: var(--kpg-accent) !important;
}
.bfusion-root--hc .kpg-tile__value {
  color: var(--kpg-text-strong, #fff) !important;
}
.bfusion-root--hc .kpg-tile__label,
.bfusion-root--hc .kpg-tile__sub,
.bfusion-root--hc .kpg-id__meta,
.bfusion-root--hc .kpg-legend,
.bfusion-root--hc .kpg-legend__refresh,
.bfusion-root--hc .kpg-rail__title,
.bfusion-root--hc .kpg-rail__divider,
.bfusion-root--hc .kpg-insight__text,
.bfusion-root--hc .kpg-field__label,
.bfusion-root--hc .kpg-field__hint {
  color: var(--kpg-text-strong, #fff) !important;
}
.bfusion-root--hc .kpg-th,
.bfusion-root--hc .kpg-th--frozen {
  background: var(--kpg-bg-panel, #000) !important;
  color: var(--kpg-text-strong, #fff) !important;
  border-bottom: 2px solid var(--kpg-text-strong, #fff) !important;
}
.bfusion-root--hc .kpg-td,
.bfusion-root--hc .kpg-td--frozen {
  background: var(--kpg-bg-panel, #000) !important;
  color: var(--kpg-text-strong, #fff) !important;
  border-bottom: 1px solid var(--kpg-text-strong, #fff) !important;
}
.bfusion-root--hc .kpg-grid--striped tbody .kpg-row:nth-of-type(even) .kpg-td {
  background: var(--kpg-bg-panel, #000) !important;
}
.bfusion-root--hc .kpg-pill,
.bfusion-root--hc .kpg-rag__count {
  background: transparent !important;
  border: 1.5px solid currentColor !important;
}
.bfusion-root--hc .kpg-pill__icon,
.bfusion-root--hc .kpg-dot,
.bfusion-root--hc .kpg-rag__dot {
  outline: 1.5px solid var(--kpg-text-strong, #fff);
  outline-offset: -1px;
}
.bfusion-root--hc .kpg-prog__bar {
  background: transparent;
  border: 1px solid var(--kpg-text-strong, #fff);
}
.bfusion-root--hc .kpg-bullet__range {
  background: transparent;
  border: 1px solid var(--kpg-text-strong, #fff);
}
.bfusion-root--hc .kpg-td--heat[style] {
  background: var(--kpg-bg-panel, #000) !important;
}
.bfusion-root--hc .kpg-row:hover .kpg-td,
.bfusion-root--hc .kpg-row:hover .kpg-td--frozen {
  background: var(--kpg-accent, #00f) !important;
  color: var(--kpg-bg-panel, #000) !important;
}
.bfusion-root--hc .kpg-row--selected .kpg-td,
.bfusion-root--hc .kpg-row--selected .kpg-td--frozen {
  background: var(--kpg-accent, #00f) !important;
  color: var(--kpg-bg-panel, #000) !important;
}
/* ========================================================================== */
/* Column Configure Dialog                                                    */
/* ========================================================================== */
.kpg-dialog {
  position: absolute;
  inset: 0;
  z-index: 40;
  background: rgba(15, 23, 42, 0.32);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.kpg-dialog__panel {
  background: #ffffff;
  border-radius: 8px;
  width: 100%;
  max-width: 520px;
  max-height: 86%;
  display: flex;
  flex-direction: column;
  box-shadow: 0 20px 50px rgba(15, 23, 42, 0.32);
  overflow: hidden;
}
.kpg-dialog__header {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 600;
  color: #0f172a;
  background: #f6f7f9;
  border-bottom: 1px solid #e3e6ec;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.kpg-dialog__title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kpg-dialog__moves {
  display: inline-flex;
  gap: 6px;
  flex-shrink: 0;
}
.kpg-dialog__body {
  padding: 16px 20px 8px;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}
.kpg-dialog__footer {
  padding: 12px 20px;
  background: #f6f7f9;
  border-top: 1px solid #e3e6ec;
  display: flex;
  align-items: center;
  gap: 10px;
}
.kpg-dialog__footer-spacer {
  flex: 1;
}
.kpg-btn--reset {
  color: #94a3b8;
}
.kpg-btn--reset:hover {
  color: #0f172a;
}
.kpg-field {
  margin-bottom: 14px;
}
.kpg-field--row {
  display: flex;
  gap: 12px;
}
.kpg-field--checkbox label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: #0f172a;
  cursor: pointer;
}
.kpg-field--checkbox input {
  margin: 0;
}
.kpg-field--section {
  margin-top: 6px;
  padding-top: 14px;
  border-top: 1px solid #e3e6ec;
}
.kpg-field__sectionhead {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #0f172a;
  margin-bottom: 4px;
}
.kpg-field__half {
  flex: 1;
  min-width: 0;
}
.kpg-field__label {
  display: block;
  font-size: 11.5px;
  font-weight: 600;
  color: #475569;
  margin-bottom: 5px;
}
.kpg-field__select,
.kpg-field__input {
  width: 100%;
  box-sizing: border-box;
  padding: 7px 10px;
  border: 1px solid #e3e6ec;
  border-radius: 4px;
  font-size: 12.5px;
  color: #0f172a;
  background: #ffffff;
  outline: 0;
  font-family: inherit;
}
.kpg-field__select:focus,
.kpg-field__input:focus {
  border-color: var(--kpg-header-band);
  box-shadow: 0 0 0 2px rgba(139, 26, 46, 0.1);
}
.kpg-field__hint {
  margin-top: 5px;
  font-size: 11px;
  color: #94a3b8;
  line-height: 1.4;
}
.kpg-checklist {
  border: 1px solid #e3e6ec;
  border-radius: 4px;
  max-height: 160px;
  overflow-y: auto;
  background: #ffffff;
  padding: 4px 0;
}
.kpg-checklist__item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  font-size: 12px;
  color: #0f172a;
  cursor: pointer;
  user-select: none;
}
.kpg-checklist__item:hover {
  background: #f6f7f9;
}
.kpg-checklist__item input {
  margin: 0;
  flex-shrink: 0;
}
/* Anchor row — the tile's own measure shown at the top of the trend list. Always
 * included; not interactive. Visually distinct so users see what's plotted. */
.kpg-checklist__item--anchor {
  background: rgba(29, 78, 216, 0.06);
  /* same as --kpg-accent at 6% */
  border-bottom: 1px solid #e3e6ec;
  color: #0f172a;
  cursor: default;
  font-weight: 600;
}
.kpg-checklist__item--anchor:hover {
  background: rgba(29, 78, 216, 0.06);
}
.kpg-checklist__item--anchor input[disabled] {
  accent-color: var(--kpg-accent, #1d4ed8);
  opacity: 1;
}
.kpg-checklist__tag {
  margin-left: auto;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--kpg-accent, #1d4ed8);
  background: rgba(29, 78, 216, 0.1);
  padding: 2px 7px;
  border-radius: 999px;
  flex-shrink: 0;
}
.kpg-btn {
  padding: 7px 18px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.12s ease;
  min-width: 88px;
  font-family: inherit;
}
.kpg-btn--ghost {
  background: #ffffff;
  color: #0f172a;
  border-color: #e3e6ec;
}
.kpg-btn--ghost:hover {
  background: #f6f7f9;
  border-color: #cbd5e1;
}
.kpg-btn--primary {
  background: #4361ee;
  color: #ffffff;
  border-color: #4361ee;
}
.kpg-btn--primary:hover {
  background: #3651d9;
  border-color: #3651d9;
}
.kpg-btn--mini {
  padding: 4px 10px;
  font-size: 11px;
  min-width: 0;
  background: #ffffff;
  color: #0f172a;
  border-color: #e3e6ec;
  font-weight: 500;
  border-radius: 4px;
}
.kpg-btn--mini:hover:not(:disabled) {
  background: #f6f7f9;
  border-color: #cbd5e1;
}
.kpg-btn--mini:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.kpg-field__hint code {
  background: #eef1f4;
  padding: 1px 5px;
  border-radius: 3px;
  font-size: 10.5px;
  font-family: "Cascadia Mono", "Consolas", monospace;
}
